12	// ── Content size limits (bytes) ─────────────────────────────────────────────────
13	// Truncate content before buffering to keep memory and payload sizes bounded.
14	
15	/** Maximum size for user message content. */
16	const MAX_USER_MESSAGE_SIZE = 10_240;
17	
18	/** Maximum size for assistant message content. */
19	const MAX_ASSISTANT_MESSAGE_SIZE = 10_240;
20	
21	/** Maximum size for tool result content blocks. */
22	const MAX_TOOL_RESULT_SIZE = 5_120;
23	
24	/** Maximum estimated JSON size for a single event before it is dropped. */
25	const MAX_EVENT_SIZE = 51_200;
26	
27	/**
28	 * Truncate a string to a maximum byte length (UTF-8 approximation).
29	 */
30	function truncate(str: string, maxBytes: number): string {
31		if (str.length <= maxBytes) {
32			return str;
33		}
34		return str.slice(0, maxBytes) + '... [truncated]';
35	}
36	
37	/**
38	 * Rough estimate of the JSON-serialized size of an event.
39	 * Avoids the cost of actual serialization.
40	 */
41	function estimateEventSize(event: SessionEvent): number {
42		// Base overhead: id (36) + timestamp (24) + type (~30) + parentId (36) + structure (~50)
43		let size = 176;
44		const data = event.data;
45		for (const value of Object.values(data)) {
46			if (typeof value === 'string') {
47				size += value.length;
48			} else if (typeof value === 'object' && value !== null) {
49				// Rough estimate for nested objects
50				size += JSON.stringify(value).length;
51			} else {
52				size += 10;
53			}
54		}
55		return size;
56	}
