59	 * Tracks per-session state needed for event translation.
60	 */
61	export interface SessionTranslationState {
62		/** Whether session.start has been emitted. */
63		started: boolean;
64		/** ID of the last event emitted (for parentId chaining). */
65		lastEventId: string | null;
66		/** Number of events dropped due to size gate. */
67		droppedCount: number;
68	}
