87	/**
88	 * Extract absolute file path from tool arguments if available.
89	 * Handles both CLI-style (edit/create with `path`) and VS Code-style tools
90	 * that use `filePath`, as well as `apply_patch` which encodes paths in the patch input.
91	 * @internal Exported for testing.
92	 */
93	export function extractFilePath(toolName: string, toolArgs: unknown): string | undefined {
94		if (!FILE_TRACKING_TOOLS.has(toolName)) { return undefined; }
95		if (typeof toolArgs !== 'object' || toolArgs === null) { return undefined; }
96		const args = toolArgs as Record<string, unknown>;
97	
98		// VS Code tools use 'filePath', CLI tools use 'path', list_dir uses 'path',
99		// create_directory uses 'dirPath'
100		const filePath = args.filePath ?? args.path ?? args.dirPath;
101		if (typeof filePath === 'string') { return filePath; }
102	
103		// multi_replace_string_in_file stores filePath in each replacement item
104		if (toolName === 'multi_replace_string_in_file' && Array.isArray(args.replacements)) {
105			const first = args.replacements[0];
106			if (typeof first === 'object' && first !== null) {
107				const fp = (first as Record<string, unknown>).filePath;
108				if (typeof fp === 'string') { return fp; }
109			}
110		}
111	
112		// apply_patch encodes file paths in the patch input text
113		if (toolName === 'apply_patch' && typeof args.input === 'string') {
114			return extractFirstFileFromPatch(args.input);
115		}
116	
117		return undefined;
118	}
