120	/**
121	 * Extract the first file path from an apply_patch input string.
122	 * Matches lines like `*** Update File: /path/to/file` or `*** Add File: /path`.
123	 */
124	function extractFirstFileFromPatch(input: string): string | undefined {
125		const match = input.match(/^\*\*\*\s+(?:Update|Add|Delete)\s+File:\s*(.+)$/m);
126		return match?.[1]?.trim();
127	}
